use super::*;

/// What arrives — and the WORST month, which is the number a plan has to survive.
///
/// The worst month leads. An average income reads as more certain than it is, and every downstream
/// question (runway, what payment is sustainable, whether a transfer is safe) turns on the low
/// months rather than the typical one.
pub fn render_income(a: &income::IncomeAnalysis, expected: crate::money::Money, notes: &[String]) -> String {
    let mut out = String::new();
    if a.sources.is_empty() && a.one_off.is_empty() {
        out.push_str("no money arriving in what has been read\n");
        for n in notes {
            out.push_str(&format!("  · {n}\n"));
        }
        return out;
    }
    out.push_str(&format!(
        "worst month {} · usual {} · best {} — over {} whole month(s)\n\n",
        crate::money::format_minor(a.worst_month.minor),
        crate::money::format_minor(a.typical_month.minor),
        crate::money::format_minor(a.best_month.minor),
        a.months_observed,
    ));
    for s in &a.sources {
        out.push_str(&format!(
            "  {:<22} {:<12} {:>12} /mo  {} · low {}\n",
            clip(&s.label, 22),
            s.cadence.label(),
            crate::money::format_minor(s.monthly_equivalent.minor),
            s.stability.label(),
            crate::money::format_minor(s.low.minor),
        ));
    }
    if !a.sources.is_empty() {
        out.push_str(&format!("\n  expected  {} a month from repeating sources\n", crate::money::format_minor(expected.minor)));
    }
    if !a.one_off.is_empty() {
        // NOT folded into the expectation. A tax refund is not income you can plan on receiving again.
        out.push_str(&format!("\n  {} one-off receipt(s), NOT counted as income you can plan on:\n", a.one_off.len()));
        for t in &a.one_off {
            out.push_str(&format!("    {} {:<26} {}\n", t.date, t.description, crate::money::format_minor(t.amount.minor)));
        }
    }
    // Coverage is stated rather than implied. Two months is not an income pattern, and the figure
    // above reads exactly the same whether it rests on two months or twenty.
    if a.months_observed < 3 {
        out.push_str(&format!("\n  · {} whole month(s) is too thin to call a pattern — these figures will move\n", a.months_observed));
    }
    for n in notes {
        out.push_str(&format!("  · {n}\n"));
    }
    out
}
